# GC content overall and in sliding windows
def gc(s): return (s.count('G')+s.count('C'))/len(s)
print('overall GC %.3f' % gc(seq))
W=150
print('windows (pos, gc):')
for i in range(0, len(seq)-W+1, W):
    print(i, '%.3f' % gc(seq[i:i+W]))

# ORF finding all six frames
codon_table = {}
bases='TCAG'
aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
i=0
for b1 in bases:
    for b2 in bases:
        for b3 in bases:
            codon_table[b1+b2+b3]=aas[i]; i+=1

def revcomp(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]

def orfs(seq):
    out=[]
    for strand,label in [(seq,'+'),(revcomp(seq),'-')]:
        L=len(seq)
        for f in range(3):
            i=f
            while i < len(strand)-2:
                c=strand[i:i+3]
                if c=='ATG':
                    # extend to stop
                    j=i
                    while j < len(strand)-2:
                        aa=codon_table.get(strand[j:j+3],'X')
                        if aa=='*':
                            if (j+3-i)>=100:
                                out.append((label,f,(i),(j+3),(j+3-i),strand[i:j+3]))
                            break
                        j+=3
                    i=j+3
                else:
                    i+=3
    return out

for s,f,st,en,ln,orf in sorted(orfs(seq), key=lambda x:-x[4]):
    print(s,f,st+1,en,ln)
